/// TEST KEY. Seed of the fake authority's first signing key.
pub const TEST_AUTHORITY_KEY_SEED: [u8; 32] = [0x5a; 32];
/// TEST KEY. Seed of the holder key used by fixtures.
pub const TEST_HOLDER_KEY_SEED: [u8; 32] = [0x3c; 32];
/// TEST SECRET. The fake authority's digest root.
pub const TEST_DIGEST_ROOT: [u8; 32] = [0x42; 32];
/// TEST SECRET. The fake authority's cursor sealing key.
pub const TEST_CURSOR_KEY: [u8; 32] = [0x24; 32];

pub const TEST_ISSUER: &str = "https://authority.example.test/api/lifecycle/v1";
pub const TEST_HOLDER_KIND: &str = "engine";
/// 2026-11-17T12:00:00Z.
pub const TEST_START_WALL_MS: i64 = 1_794_916_800_000;

/// A profile with no real authority's names in it.
pub fn neutral_profile() -> WireProfile {
    let strings = |values: &[&str]| values.iter().map(|v| (*v).to_owned()).collect();
    WireProfile {
        typ_list_request: "example-holdings-listreq+jwt".into(),
        typ_list_page: "example-holdings-list+jwt".into(),
        typ_keyset: "example-lifecycle-keyset+jwt".into(),
        typ_report_request: "example-obligation-report+jwt".into(),
        typ_report_ack: "example-obligation-ack+jwt".into(),
        outcome_header: "Example-Lifecycle-Outcome".into(),
        audience_prefix: "example-lifecycle:".into(),
        authority_key_id_prefix: "ak-".into(),
        resource_kinds: strings(&["collection", "archive", "volume"]),
        accepted_resource_kinds: strings(&["collection", "archive"]),
        engine: Some(EngineProfile {
            holder_kind: TEST_HOLDER_KIND.into(),
            pinned_resource_kind: "collection".into(),
        }),
        obligation_reasons: strings(&["retire", "holder-decommission"]),
    }
}

/// TEST-ONLY capability verifier. It "signs" a capability as
/// `cap.<iat>.<exp>.<mac>` with a published test key and accepts only those;
/// anything else, including a bare or forged timestamp, is rejected.
pub struct TestCapabilityVerifier;

impl TestCapabilityVerifier {
    fn mac(iat_s: i64, exp_s: i64) -> String {
        use sha2::{Digest, Sha256};
        crate::b64::encode(&Sha256::digest(
            format!("test-cap-key|{iat_s}|{exp_s}").as_bytes(),
        ))
    }

    pub fn issue(iat_s: i64, exp_s: i64) -> Vec<u8> {
        format!("cap.{iat_s}.{exp_s}.{}", Self::mac(iat_s, exp_s)).into_bytes()
    }

    pub fn forge(iat_s: i64, exp_s: i64) -> Vec<u8> {
        format!("cap.{iat_s}.{exp_s}.{}", "f".repeat(43)).into_bytes()
    }
}

impl crate::engine::CapabilityVerifier for TestCapabilityVerifier {
    type Rejection = &'static str;

    fn verify(&self, capability: &[u8]) -> Result<crate::engine::CapabilityTimes, &'static str> {
        let text = std::str::from_utf8(capability).map_err(|_| "utf-8")?;
        let mut parts = text.split('.');
        let (Some("cap"), Some(iat), Some(exp), Some(mac), None) = (
            parts.next(),
            parts.next(),
            parts.next(),
            parts.next(),
            parts.next(),
        ) else {
            return Err("shape");
        };
        let (iat_s, exp_s) = (
            iat.parse().map_err(|_| "iat")?,
            exp.parse().map_err(|_| "exp")?,
        );
        if mac != Self::mac(iat_s, exp_s) {
            return Err("signature");
        }
        Ok(crate::engine::CapabilityTimes { iat_s, exp_s })
    }
}

/// A deterministic, valid 43-character pin id derived from a label.
pub fn pin_id(label: &str) -> String {
    use sha2::{Digest, Sha256};
    crate::b64::encode(&Sha256::digest(label.as_bytes()))
}

pub type TestHolder = Holder<MemoryStore, FakeAuthority>;

/// Why a rig could not start its holder.
#[derive(Debug)]
pub enum RigError {
    Startup(StartupError),
    Config(crate::holder::ConfigError),
}

impl RigError {
    pub fn code(&self) -> &'static str {
        match self {
            Self::Startup(error) => error.code(),
            Self::Config(_) => "holder_config",
        }
    }
}

/// One enrolled holder wired to a fake authority, fake clock, memory store
/// and fake data root, all sharing state so tests can inspect and mutate.
pub struct Rig {
    pub clock: Arc<FakeClock>,
    pub authority: FakeAuthority,
    pub events: Arc<MemorySink>,
    pub store: MemoryStore,
    pub data_root: FakeDataRoot,
    pub io_faults: IoFaults,
    pub dir: PathBuf,
    pub config: HolderConfig,
    pub purger: MemoryPurger,
    holder: Option<TestHolder>,
}

impl Rig {
    /// Enrolls a holder in `dir` under the neutral profile and starts it.
    pub fn new(dir: &Path) -> Self {
        Self::with_profile(dir, neutral_profile(), "example-lifecycle/v1")
    }

    /// Enrolls a holder under `profile`. Its kind is the engine section's
    /// holder kind, or `device` for a profile without one.
    pub fn with_profile(dir: &Path, profile: WireProfile, digest_salt: &str) -> Self {
        let holder_kind = profile
            .engine
            .as_ref()
            .map_or_else(|| "device".to_owned(), |engine| engine.holder_kind.clone());
        let clock = Arc::new(FakeClock::new(TEST_START_WALL_MS, 1_000_000));
        let authority = FakeAuthority::new(
            AuthorityConfig {
                profile: profile.clone(),
                issuer: TEST_ISSUER.into(),
                digest_salt: digest_salt.into(),
                holder_kind: holder_kind.clone(),
                serve_seconds: 900,
                relist_seconds: 300,
            },
            clock.clone(),
        );
        let key = HolderKey::from_seed(TEST_HOLDER_KEY_SEED);
        let (holder_id, jwks) = authority.enroll(&key);
        let io_faults = IoFaults::default();
        {
            let holder_dir = HolderDir::open(dir, &[]).expect("holder dir");
            startup::write_key(&holder_dir, &FsIo, &key).expect("key");
            startup::enroll(
                holder_dir,
                Box::new(FsIo),
                clock.clone(),
                &EnrollParams {
                    holder_id: &holder_id,
                    holder_kind: &holder_kind,
                    issuer: TEST_ISSUER,
                    jwks: &jwks,
                    authority_key_id_prefix: &profile.authority_key_id_prefix,
                },
            )
            .expect("enroll");
        }
        let engine = profile.engine.as_ref().map(|_| {
            EngineSettings::new(30, crate::engine::stale_serve::DEFAULT_STALE_SERVE_S)
                .expect("engine settings")
        });
        let config = HolderConfig {
            profile,
            page_size: crate::holder::DEFAULT_PAGE_SIZE,
            engine,
        };
        let mut rig = Self {
            clock,
            authority,
            events: Arc::new(MemorySink::default()),
            store: MemoryStore::default(),
            data_root: FakeDataRoot::default(),
            io_faults,
            dir: dir.to_path_buf(),
            config,
            purger: MemoryPurger::default(),
            holder: None,
        };
        rig.restart().expect("start");
        rig
    }

    /// Drops the running holder (its lock and all volatile state) and starts
    /// a new one from the holder directory.
    pub fn restart(&mut self) -> Result<(), RigError> {
        self.holder = None;
        let dir = HolderDir::open(&self.dir, &[]).map_err(|e| {
            RigError::Startup(match e {
                crate::state::DirError::Io(io) => StartupError::Io(io),
                other => StartupError::DataRoot(other.to_string()),
            })
        })?;
        let started = startup::start(
            dir,
            Box::new(self.io_faults.io()),
            self.clock.clone(),
            &self.data_root,
            self.events.as_ref(),
        )
        .map_err(RigError::Startup)?;
        let holder = Holder::new(
            started,
            self.config.clone(),
            self.store.clone(),
            self.authority.clone(),
            self.clock.clone(),
            self.events.clone(),
        )
        .map_err(RigError::Config)?;
        self.holder = Some(holder);
        Ok(())
    }

    pub fn holder(&mut self) -> &mut TestHolder {
        self.holder.as_mut().expect("holder running")
    }

    pub fn gate(&self) -> ServingGate {
        self.holder.as_ref().expect("holder running").gate()
    }

    /// The engine profile's gate; panics for a holder without one.
    pub fn engine_gate(&self) -> EngineGate {
        self.holder
            .as_ref()
            .expect("holder running")
            .engine_gate()
            .expect("engine profile")
    }

    /// One purge pass: detach, then delete and verify.
    pub fn purge(
        &mut self,
    ) -> Result<crate::purge::PurgeSummary, crate::purge::ObligationsRefused> {
        let mut purger = self.purger.clone();
        self.holder().purge_detach(&mut purger)?;
        self.holder().purge_delete_and_verify(&mut purger)
    }

    /// One report pass against the rig's purger.
    pub fn report(
        &mut self,
    ) -> Result<crate::report::ReportSummary, crate::purge::ObligationsRefused> {
        let purger = self.purger.clone();
        self.holder().report_once(&purger)
    }

    /// Advances both clocks, past the list-start spacing by default.
    pub fn advance(&self, ms: u64) {
        self.clock.advance(ms);
    }

    /// Advances past the list-start spacing and any backoff, and lists once.
    pub fn relist(&mut self) -> crate::holder::ListOutcome {
        use crate::clock::Clock;
        let now = self.clock.mono_ms();
        let start_at = self.holder().scheduler().next_start_at();
        self.advance(
            start_at
                .saturating_sub(now)
                .max(crate::schedule::LIST_START_SPACING_MS),
        );
        self.holder().list_once()
    }
}
